const FooterBg = () => {
    const { pathname } = useLocation();

    const isHomePage = pathname === '/'

    return (
        <>

            <motion.div
                initial={{ y: 200, opacity: 0 }}
                whileInView={{ y: 0, opacity: 1 }}
                viewport={{ once: true }}
                transition={{
                    duration: 0.3,
                    delay: 0.8,
                    type: "spring",
                    stiffness: 50,
                    damping: 12
                }}
                className={clsx(isHomePage && 'desktop:drop-shadow-[0_-50px_30px_#00000015]', "absolute mx-auto flex inset-0 z-10 pointer-events-none *:pointer-events-none")}

            >
                <Trees />
            </motion.div>

            <RoadDesktop className='tablet:block hidden absolute w-full bottom-0 z-0 pointer-events-none' />
            <RoadMobile preserveAspectRatio='none' className='block min-w-full object-cover tablet:hidden pointer-events-none mx-auto absolute bottom-12 z-10' />
            <GradientMobile preserveAspectRatio='none' className='block min-w-full object-cover tablet:hidden pointer-events-none mx-auto absolute bottom-0 z-0' />
        </>
    );
};

export default FooterBg;
